# Your solution code here
def solution(input_data):
    """
    Solve the microwave banana problem.
    For each banana count from 1 to m, find the earliest time-step to reach it.
    """
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(n):
        parts = list(map(int, lines[i+1].split()))
        t = parts[0]
        x_num = parts[1]
        y = parts[2]
        x_i = x_num / 100000.0
        operations.append((t, x_num, y, x_i))

    # ans[j] stores the earliest time-step to reach j bananas
    ans = [-1] * (m + 1)

    # Track all reachable banana counts at the end of each time-step
    current_reachable = {0}

    for t_step in range(n):
        next_reachable = set()
        t_i, x_num, y_i, x_i = operations[t_step]

        for k in current_reachable:
            temp_k = k

            # Try applying operation a times, where 0 <= a <= y_i
            for a in range(y_i + 1):
                new_k = temp_k

                # Apply the update 'a' times
                for _ in range(a):
                    if t_i == 1:
                        # Type 1: k := ceil(k + x_i)
                        value = new_k + x_i
                        d = value - new_k
                        if d >= 1.0:
                            new_k = int(value) + (0 if value.is_integer() else 1)
                        else:
                            # d is the fractional part, need ceiling
                            if d > 0:
                                new_k = int(value) + 1
                            else:
                                new_k = int(value)
                    else:  # Type 2: k := ceil(k * x_i)
                        # Value = ceil(k * x_i)
                        value = new_k * x_i
                        new_k = int(value) + (0 if value.is_integer() else 1)

                    # Early break if new_k is valid
                    if new_k > m or new_k < 0:
                        new_k = m + 1  # Mark as out of bounds
                        break
                    break  # Limit break if already valid

                if 0 <= new_k <= m:
                    next_reachable.add(new_k)

        # For each value newly reached (first time), record the time-step
        for k in next_reachable:
            if ans[k] == -1:
                ans[k] = t_step + 1

        current_reachable = next_reachable

    # Return only answers for bananas 1 through m
    return ' '.join(str(ans[j]) for j in range(1, m + 1))

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:n+1]]

    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find connected component
                component = [(i, j)]
                visited[i][j] = True
                queue = [(i, j)]

                while queue:
                    r, c = queue.pop(0)

                    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and not visited[nr][nc]:
                            visited[nr][nc] = True
                            component.append((nr, nc))
                            queue.append((nr, nc))

                # Find bounding box
                min_r = min(r for r, c in component)
                max_r = max(r for r, c in component)
                min_c = min(c for r, c in component)
                max_c = max(c for r, c in component)

                # Fill bounding box with '.' (remove walls)
                for r in range(min_r, max_r + 1):
                    for c in range(min_c, max_c + 1):
                        if grid[r][c] == '*':
                            grid[r][c] = '.'

    return '\n'.join(''.join(row) for row in grid)

