class LazySegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

        # Initialize leaves with actual array values
        for i in range(self.n):
            self.tree[self.size + i] = data[i]
        # Build tree
        for i in range(self.size - 1, 0, -1):
            self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]

    def push(self, node, start, end):
        if self.lazy[node] != 0:
            mid = (start + end) // 2
            left = 2 * node
            right = 2 * node + 1

            self.lazy[left] += self.lazy[node]
            self.tree[left] += self.lazy[node] * (mid - start + 1)
            self.lazy[right] += self.lazy[node]
            self.tree[right] += self.lazy[node] * (end - mid)

            self.lazy[node] = 0

    def update_range(self, l, r, val):
        """Update [l, r] with value"""
        self._update_range(1, 0, self.size - 1, l, r, val)

    def _update_range(self, node, start, end, l, r, val):
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.tree[node] += val * (end - start + 1)
            self.lazy[node] += val
            return
        self.push(node, start, end)
        mid = (start + end) // 2
        self._update_range(2 * node, start, mid, l, r, val)
        self._update_range(2 * node + 1, mid + 1, end, l, r, val)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def get_point(self, idx):
        """Get value at index idx"""
        return self._get_point(1, 0, self.size - 1, idx)

    def _get_point(self, node, start, end, idx):
