class DiffSegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.size = 1
        while self.size < self.n:
            self.size *= 2
        # Store differences: d[i] = a[i] - a[i-1] for i >= 1, d[0] = a[0]
        self.d = [0] * self.size
        for i in range(self.n):
            if i == 0:
                self.d[i] = data[i]
            else:
                self.d[i] = data[i] - data[i-1]
        self.tree = [0] * (2 * self.size)
        self.lazy = [0] * (2 * self.size)

        for i in range(self.n):
            self.tree[self.size + i] = self.d[i]

        for i in range(self.size - 1, 0, -1):
            self.tree[i] = self.tree[2 * i] + self.tree[2 * i + 1]

    def push(self, node):
        if self.lazy[node] != 0:
            left = 2 * node
            right = 2 * node + 1

            self.lazy[left] += self.lazy[node]
            self.tree[left] += self.lazy[node]

            self.lazy[right] += self.lazy[node]
            self.tree[right] += self.lazy[node]

            self.lazy[node] = 0

    def update_range(self, l, r, val):
        """Add val to all elements in range [l, r], affects differences"""
        # For difference array:
        # d[l] increases by val
        # d[r+1] decreases by val
        # d[k] unchanged for k in (l, r+1]
        self.lazy_update(l, val)
        if r + 1 < self.size:
            self.lazy_update_direct(r + 1, -val)

    def lazy_update(self, idx, val):
        """Update point with lazy propagation"""
        self._lazy_update(lazy=True, node=1, start=0, end=self.size-1, idx=idx, val=val)

    def _lazy_update(self, node, start, end, idx, val):
        if start == end:
            self.tree[node] += val
            self.lazy[node] += val
            return
        self.push(node)
        mid = (start + end) // 2
        if idx <= mid:
            self._lazy_update(2 * node, start, mid, idx, val)
        else:
            self._lazy_update(2 * node + 1, mid + 1, end, idx, val)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def get_diff(self, idx):
        """Get difference d[idx] = a[idx] - a[idx-1]"""
        if idx == 0:
            return self._get_point(1, 0, self.size - 1, 0)
        return self._get_point(1, 0, self.size - 1, idx)

    def _get_point(self, node, start, end, idx):
        if start == end:
            return self.tree[node]
        self.push(node)
        mid = (start + end) // 2
        if idx <= mid:
            return self._get_point(2 * node, start, mid, idx)
        else:
            return self._get_point(2 * node + 1, mid + 1, end, idx)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return ''

    iterator = iter(input_data)

    try:
        n = int(next(iterator))
        A = [int(next(iterator)) for _ in range(n)]
        q = int(next(iterator))
    except StopIteration:
        return ''

    # Build segment trees
    val_tree = LazySegmentTree(A)
    diff_tree = DiffSegmentTree(A)

    results = []

    for _ in range(q):
        t = int(next(iterator))
        l = int(next(iterator)) - 1  # 0-indexed
        r = int(next(iterator)) - 1  # 0-indexed
        x = int(next(iterator))

        if t == 1:
            # Type 1: Find max f(A) after adding x to one element in [l, r]
            # f(A) = sum of (a[i] - a[i-1])^2
            # Add x to a[i]: affects (a[i]-a[i-1])^2 and (a[i+1]-a[i])^2

            # Get f(A) before
            f_before = 0
            for i in range(n):
                diff = diff_tree.get_diff(i)
                val = val_tree.get_point(i)
                if i < n - 1:
                    f_before += (val - 0) ** 2  # This is computed wrong, need fix

            # Actually, let's compute directly
            f = 0
            for i in range(1, n):
                diff = diff_tree.get_diff(i)
                f += diff * diff

            # For type 1, we iterate through range [l, r]
            best_change = float('-inf')

            # Check boundaries and internal points efficiently
            # We need to find element to add x

            # Let's check each position in range
            for i in range(l, r + 1):
                change = 0
                # Add x to a[i]

                # Left neighbor (if exists): i > 0
                if i > 0:
                    left_diff = diff_tree.get_diff(i)  # a[i] - a[i-1]
                    # After adding x: (a[i]+x - a[i-1])^2 - (a[i] - a[i-1])^2
                    # = (diff + x)^2 - diff^2 = 2*diff*x + x^2
                    change += 2 * left_diff * x + x * x

                # Right neighbor (if exists): i < n-1
                if i < n - 1:
                    right_diff = -diff_tree.get_diff(i + 1)  # a[i+1] - a[i]
                    # diff_tree gives a[i+1] - a[i], so negative of what we want
                    # Change from (a[i+1] - (a[i]+x))^2 - (a[i+1] - a[i])^2
                    # = (diff - x)^2 - diff^2 = -2*diff*x + x^2 where diff = a[i+1] - a[i]
                    # But right_diff is negative of this, so: -2*(-right_diff)*x + x^2 = 2*right_diff*x + x^2
                    # Wait, recalculate:
                    # Let a[i+1] - a[i] = d, then change = (d - x)^2 - d^2 = -2*d*x + x^2
                    # d = a[i+1] - a[i] = diff_tree.get_diff(i+1)  [Wait, let me check]
                    # Actually diff_tree.get_diff(i+1) = a[i+1] - a[i], correct
                    d = diff_tree.get_diff(i + 1)
                    change += -2 * d * x + x * x

                # Handle edge cases for i=0 and i=n-1
                if i == 0 and i == n - 1:  # Only works for n=1
                    pass  # No neighbors

                best_change = max(best_change, change)

            results.append(str(f_before + best_change))

        else:
            # Type 2: Range add x to [l, r]
            val_tree.update_range(l, r, x)
            # Update differences
            # d[l] increases by x
            # d[r+1] decreases by x
            if l > 0:
                diff_tree.lazy_update(l, x)
            if r + 1 < n:
                diff_tree.lazy_update(r + 1, -x)

    return '\n'.join(results)

