import math

def dist_sq(p1, p2):
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2 + (p1[2] - p2[2])**2

def solve(input_str):
    import random

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        parts = list(map(float, lines[i].split()))
        points.append((parts[0], parts[1], parts[2]))

    random.seed()
    random.shuffle(points)

    def on_boundary(point, boundary):
        if len(boundary) == 0:
            return False
        if len(boundary) == 1:
            return abs(dist_sq(point, boundary[0]) < 1e-10)
        if len(boundary) == 2:
            c = ((boundary[0][0] + boundary[1][0])/2, (boundary[0][1] + boundary[1][1])/2,
                 (boundary[0][2] + boundary[1][2])/2)
            r2 = dist_sq(boundary[0], c)
            return abs(dist_sq(point, c) - r2) < 1e-10
        if len(boundary) == 3:
            a = dist_sq(point, boundary[0])
            b = dist_sq(point, boundary[1])
            c = dist_sq(point, boundary[2])
            d = dist_sq(boundary[0], boundary[1])
            e = dist_sq(boundary[1], boundary[2])
            f = dist_sq(boundary[2], boundary[0])
            return abs(a**2 + b**2 + c**2 - d**2 - e**2 - f**2) < 1e-8
        return True

    def get_minimum_enclosing(boundary):
        if len(boundary) == 0:
            return (0.0, 0.0, 0.0, 0.0)
        if len(boundary) == 1:
            return (boundary[0][0], boundary[0][1], boundary[0][2], 0.0)
        if len(boundary) == 2:
            c = ((boundary[0][0] + boundary[1][0])/2, (boundary[0][1] + boundary[1][1])/2,
                 (boundary[0][2] + boundary[1][2])/2)
            r2 = dist_sq(boundary[0], c)
            return c[0], c[1], c[2], math.sqrt(r2)
        if len(boundary) == 3:
            raise RuntimeError("Should not reach here with 3 points")
        if len(boundary) > 3:
            raise RuntimeError("Too many boundary points")

    def solve_rec(i, boundary):
        if i == n:
            center, r = get_minimum_enclosing(boundary)
            return center, r

        p = points[i]
        center, r = solve_rec(i + 1, boundary)

        d = dist_sq(p, (center[0], center[1], center[2]))

        if r == 0 or d > r + 1e-10:
            if len(boundary) >= 4:
                center, r = solve_rec(i + 1, boundary)
            elif len(boundary) >= 3:
                p2, r = solve_rec(i + 1, boundary)
                center, r = solve_rec(i + 1, boundary)
                center, r = solve_rec(i + 1, boundary)
            elif len(boundary) >= 2:
                p3, r = solve_rec(i + 1, boundary + [p])
                center, r = solve_rec(i + 1, boundary + [p])
                center, r = solve_rec(i + 1, boundary + [p], boundary)

        return center, r

    return None

