def solution(input_text):
    lines = input_text.strip().split('\n')

    if not lines:
        return '0\n'

    # Parse k, n, m
    first_line = lines[0].split()
    k, n, m = map(int, first_line)

    # Parse initial skills
    skills = list(map(int, lines[1].split()))

    # Parse improvements
    improvements = []
    for i in range(n):
        parts = list(map(int, lines[2 + i].split()))
        improvements.append({
            'id': i + 1,
            'type': parts[0],
            'skill_idx': parts[1] - 1,
            'value': parts[2]
        })

    if m == 0:
        return '0\n'

    # Calculate potential impact for each improvement
    def calc_impact(imp, skills):
        skill_idx = imp['skill_idx']
        current = skills[skill_idx]

        if imp['type'] == 1:
            return abs(imp['value'] - current)
        elif imp['type'] == 2:
            return current * imp['value']
        elif imp['type'] == 3:
            return current * (imp['value'] - 1)

    # Sort improvements by impact descending
    sorted_imps = sorted(improvements, key=calc_impact, reverse=True)

    # Select top m improvements
    selected = sorted_imps[:m]

    # Group by skill and sort by type (Type 3 first, then Type 2, then Type 1)
    # Within each type, higher value first
    skill_imps = [[] for _ in range(k)]
    for imp in selected:
        skill_imps[imp['skill_idx']].append(imp)

    # Sort each skill's improvements
    for i in range(k):
        if skill_imps[i]:
            skill_imps[i].sort(key=lambda x: (-x['value'] if x['type'] == 3 else -x['value'] if x['type'] == 2 else float('inf')))

    # Apply improvements per skill in order
    result = []
    curr_skills = list(skills)

    for skill_idx in range(k):
        for imp in skill_imps[skill_idx]:
            if imp['type'] == 1:
                curr_skills[skill_idx] = imp['value']
                result.append(imp['id'])
            elif imp['type'] == 2:
                curr_skills[skill_idx] += imp['value']
                result.append(imp['id'])
            elif imp['type'] == 3:
                curr_skills[skill_idx] *= imp['value']
                result.append(imp['id'])

    l = len(result)
    if l == 0:
        return '0\n'

    return f'{l}\n{" ".join(map(str, result))} '

def solution(input_str):
