def count_squares(matrix, n, m):
    count = 0

    # Axis-aligned squares
    for r in range(n):
        for c in range(m):
            # For each size k starting from 2
            max_k = min(n - r, m - c)
            for k in range(2, max_k + 1):
                if is_valid_axis_aligned(matrix, r, c, k, n, m):
                    count += 1

    # Diagonal squares
    for r in range(n):
        for c in range(m):
            # For diagonal squares, we try different sizes
            max_k = min(n - r - 1, m - c - 1, n - r, c) + 1 if m - c > 0 else 1
            max_k = min(max_k, n - r - 1) + 1
            for k in range(1, min(n, m) + 1):
                if r + k >= n or c - k >= 0 or c - k < 0:
                    continue

                if is_valid_diagonal(matrix, r, c, k, n, m):
                    count += 1

    return count


def is_valid_axis_aligned(matrix, r, c, k, n, m):
    # Check top row
    for j in range(c, c + k):
        if matrix[r][j] != '1':
            return False

    # Check bottom row
    for j in range(c, c + k):
        if matrix[r + k - 1][j] != '1':
            return False

    # Check left column
    for i in range(r, r + k):
        if matrix[i][c] != '1':
            return False

    # Check right column
    for i in range(r, r + k):
        if matrix[i][c + k - 1] != '1':
