        edges.append((a, b, e, i))  # store original index

    # Kruskal's algorithm to build MST
    sorted_edges = sorted(edges, key=lambda x: x[2])

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    idx_in_mst = [-1] * m
    mst_adj = [[] for _ in range(n + 1)]
    mst_count = 0

    for e, a, b, idx in sorted_edges:
        if union(a, b):
            idx_in_mst[idx] = True
            mst_adj[a].append((b, e))
            mst_adj[b].append((a, e))
            mst_count += 1
            if mst_count == n - 1:
                break

    # Build LCA with binary lifting for max edge on path
    LOG = (n).bit_length() + 1
    up = [[0] * (n + 1) for _ in range(LOG)]
    mx = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)

    stack = [(1, 0, 0, 0)]  # (current, parent, depth, max_to_parent)

    def dfs(u, p, d, w):
        visited[u] = True
        depth[u] = d
        up[0][u] = p
        mx[0][u] = w
        for v, w2 in mst_adj[u]:
            if not visited[v]:
                dfs(v, u, d + 1, w2)

    dfs(1, 0, 0, 0)

    # Build binary lifting table
    for j in range(1, LOG):
        for i in range(1, n + 1):
            if up[j-1][i] != 0:
                up[j][i] = up[j-1][up[j-1][i]]
                mx[j][i] = max(mx[j-1][i], mx[j-1][up[j-1][i]])
            else:
                up[j][i] = 0
                mx[j][i] = mx[j-1][i]

    # Query max edge on path between u and v
    def query_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        ans = 0
        # Lift u to same depth as v
        diff = depth[u] - depth[v]
        for j in range(LOG):
            if diff & (1 << j):
                ans = max(ans, mx[j][u])
                u = up[j][u]

        if u == v:
            return ans

        # Lift both until they're just below LCA
        for j in range(LOG - 1, -1, -1):
            if up[j][u] != up[j][v]:
                ans = max(ans, mx[j][u])
                ans = max(ans, mx[j][v])
                u = up[j][u]
                v = up[j][v]

        # One more step to LCA
        ans = max(ans, mx[0][u])
        ans = max(ans, mx[0][v])
        return ans

