    # BFS distance
    def bfs_dist(start, end):
        if start == end:
            return 0
        q = deque([(start, 0)])
        dist = {start: 0}
        while q:
            curr, d = q.popleft()
            for nb in adj[curr]:
                if nb not in dist:
                    dist[nb] = d + 1
                    if nb == end:
                        return dist[nb]
                    q.append((nb, d + 1))
        return 0

    # Compute subtree sizes with root = 1
    def get_sz(u, p):
        sz = 1
        for v in adj[u]:
