            if v != pr and sz[v] * 2 > total:
                return centroid(v, u, total)
        return u

    centroid_node = centroid(1, -1, sz[1])

    # Greedy assignment with distance maximization
    assigned = [False] * (n + 1)
    perm = [0] * (n + 1)
    unassigned = list(range(1, n + 1))

    idx = 0
    while idx < len(unassigned):
        src = unassigned[idx]
        best = -1
        best_d = -1

        for tgt in unassigned:
            if tgt != src:
                d = bfs_dist(src, tgt)
                if d > best_d or (d == best_d and tgt < best):
                    best = tgt
                    best_d = d

        if best != -1 and best in unassigned:
