    n = int(lines[0])

    if n == 1:
        return "1"

    # Parse edges
    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        if line.strip():
            u, v = map(int, line.split())
            adj[u].append(v)
            adj[v].append(u)

    # Build tree (root at 1)
    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    visited = [False] * (n + 1)

    def build_tree(u, p):
        visited[u] = True
        parent[u] = p
        for v in adj[u]:
            if v != p and not visited[v]:
                children[u].append(v)
                build_tree(v, u)

    build_tree(1, 0)

    # DP: dp[u] returns list of (size, max_product) pairs
    # Only keep pairs that are optimal
    @lru_cache(maxsize=None)
    def dp(u):
        if len(children[u]) == 0:
            return [(1, 1)]

        result = [(1, 1)]

        for v in children[u]:
            v_result = dp(v)
            new_result = {}

            for (sz_u, prod_u) in result:
                for (sz_v, prod_v) in v_result:
                    # Cut edge
                    key = sz_u
                    val = prod_u * prod_v
                    if key not in new_result or val > new_result[key]:
                        new_result[key] = max(new_result[key], val)

                    # Merge
                    key = sz_u + sz_v
                    val = prod_u * prod_v
                    if key not in new_result or val > new_result[key]:
                        new_result[key] = max(new_result[key], val)

            result = []
            for k, v in new_result.items():
                result.append((k, v))

        return result

    result = dp(1)
    max_prod = max(p for s, p in result)
    return str(max_prod)

