        # Count leaves in each subtree
        def count_leaves(node_idx):
            if node_info[node_idx]['type'] == 'leaf':
                return 1
            return count_leaves(node_info[node_idx]['left']) + \
                   count_leaves(node_info[node_idx]['right'])

        # Compute value for subtree rooted at node_idx
        def solve(node_idx):
            node = node_info[node_idx]
            if node['type'] == 'leaf':
                return node['value']

            num_leaves_in_subtree = count_leaves(node_idx)
            left_val = solve(node['left'])
            right_val = solve(node['right'])

            # If odd leaf count in subtree, Pieguy controls this node (wants max)
            # If even, Piegirl controls this node (wants min)
            if num_leaves_in_subtree % 2 == 1:
                return max(left_val, right_val)
            else:
                return min(left_val, right_val)

        result = solve(0)
        output.append(str(result))

    return '\n'.join(output)

