    chars = [chr(ord('a') + i) for i in range(l)]

    def char_to_type(c):
        idx = ord(c) - ord('a')
        return 'V' if idx in vowels else 'C'

    def build_word(pos, min_char_idx, word):
        if pos == n:
            # Check all rules are satisfied
            for r in rules:
                p1, t1, p2, t2 = r
                if char_to_type(word[p1-1]) == t1:
                    if char_to_type(word[p2-1]) != t2:
                        return None
            return ''.join(word)

        for c_idx in range(min_char_idx, l):
            c = chars[c_idx]
            word[pos] = c

            # Check constraints that rule this character out
            ok = True
            for r in rules:
                p1, t1, p2, t2 = r
                p1_idx, p2_idx = p1 - 1, p2 - 1

                # If pos1 is already filled
                if p1_idx < pos and word[p1_idx] != '#':
                    # Rule is triggered if word[pos1] has type t1
                    if char_to_type(word[p1_idx]) == t1:
                        # pos2 must have type t2
                        if p2_idx < pos:
                            # pos2 is filled - check
                            if char_to_type(word[p2_idx]) != t2:
                                ok = False
                                break
                        elif p2_idx == pos:
                            # pos2 is current character
                            if char_to_type(c) != t2:
                                ok = False
                                break
                        else:
                            # pos2 > pos, will be checked later

                # If pos1 is current character and its type triggers the rule
                elif p1_idx == pos and char_to_type(c) == t1:
                    if p2_idx < pos:
                        # pos2 is filled - must match t2
                        if char_to_type(word[p2_idx]) != t2:
                            ok = False
                            break
                    elif p2_idx == pos:
                        # self-trigger / self-check (but pos1 != pos2 by problem)
                        pass
                    # Else p2 > pos - deferred

                # p1 > pos - rule not triggered yet, ignore

            if ok:
                result = build_word(pos + 1, c_idx, word)
                if result is not None:
                    return result

            word[pos] = '#'

        return None

    result = build_word(0, 0, [''] * n)
    return result if result is not None else "-1"


