    for x in a:
        temp = x
        if temp > 1:
            d = 2
            while d * d <= temp:
                while temp % d == 0:
                    all_primes.add(d)
                    temp //= d
                d += 1
            if temp > 1:
                all_primes.add(temp)

    if not all_primes:
        return "0\n"

    total_operations = 0
    source = n
    sink = n + 1
    num_graph_nodes = n + 2

    pair_left = []
    pair_right = []

    for u, v in pairs:
        if u % 2 == 0:  # 0-indexed even means original odd (left side)
            pair_left.append(u)
            pair_right.append(v)
        else:  # 0-indexed odd means original even (right side)
            pair_left.append(v)
            pair_right.append(u)

    for p in all_primes:
