            if i % 2 == 0:
                dinic.add_edge(source, i, counts[i])

        # Connect odd-indexed nodes (right side) to sink
        for i in range(n):
            if i % 2 == 1:
                dinic.add_edge(i, sink, counts[i])

        # Add pair edges with infinite capacity
        for i, (u, v) in enumerate(pairs):
            dinic.add_edge(pair_left[i], pair_right[i], float('inf'))

        total_operations += dinic.max_flow(source, sink)

