    # Group consecutive heights (difference = 1)
    groups = []
    if unique_heights:
        groups.append([unique_heights[0]])
        for i in range(1, len(unique_heights)):
            if unique_heights[i] - unique_heights[i-1] == 1:
                groups[-1].append(unique_heights[i])
            else:
                groups.append([unique_heights[i]])

    best_total = 0
    best_min_h = unique_heights[0]
    best_max_h = unique_heights[0]

    # Check single-element ranges
    for h in unique_heights:
        if count[h] > best_total:
            best_total = count[h]
            best_min_h = best_max_h = h

    # Check multi-element ranges in each consecutive group
    for group in groups:
        m = len(group)
        for start in range(m):
            for end in range(start, m):
                left_h, right_h = group[start], group[end]

                valid = count[left_h] >= 1 and count[right_h] >= 1
                for k in range(start + 1, end):
                    if count[group[k]] < 2:
                        valid = False
                        break

                if valid:
                    total = sum(count[group[i]] for i in range(start, end + 1))
                    if total > best_total:
                        best_total = total
                        best_min_h, best_max_h = left_h, right_h

    # Reconstruct the valid circle arrangement
    result = []
    if best_min_h == best_max_h:
        result = [best_min_h] * best_total
    else:
        # Pattern: go up from min to max with one of each, 
        # then down with remaining amounts in reverse, 
        # ending with enough to connect back to start
        result = []
        for h in range(best_min_h, best_max_h + 1):
            result.append(h)

        for h in range(best_max_h - 1, best_min_h, -1):
            if count[h] > 1:
                result.extend([h] * (count[h] - 1))

        if count[best_min_h] > 1:
            result.extend([best_min_h] * (count[best_min_h] - 1))

        if len(result) > best_total:
            result = result[:best_total]

    return str(best_total) + "\n" + " ".join(map(str, result))


