def calculate_cost(a, k):
    """Calculate minimum cost to make all elements divisible by k"""
    n = len(a)
    cost = 0
    current_sum = 0
    for i in range(n):
        current_sum += a[i]
        if i < n - 1:
            rem = current_sum % k
            # We can either move 'rem' pieces forward or 'k-rem' backward
            cost += min(rem, k - rem)
    return cost

