from functools import lru_cache

def solution(input_str):
    parts = input_str.strip().split()
    a = int(parts[0])
    b = int(parts[1])
    n = int(parts[2])

    # Game: players alternate adding box (+1 to a) or item (+1 to b)
    # Player who causes a^b >= n loses
    # Return the loser's name

    @lru_cache(maxsize=100000)
    def can_win(a, b):
        # Returns True if current player can force opponent to lose
        if a ** b >= n:
            return False

        next_states = []
        # Try increasing a
        if pow(a + 1, b) < n:
            next_states.append((a + 1, b))
        # Try increasing b
        if pow(a, b + 1) < n:
            next_states.append((a, b + 1))

        if not next_states:
            return False

        for na, nb in next_states:
            if not can_win(na, nb):
                return True

        return False

    used = set()

    @lru_cache(maxsize=100000)
    def check(a, b):
        if a ** b >= n:
            return False
        if (a, b) in used:
            return None  # Cycle or infinite

        states = []
        if pow(a + 1, b) < n:
            states.append((a + 1, b))
        if pow(a, b + 1) < n:
            states.append((a, b + 1))

        if not states:
            used.add((a, b))
            return False

        for sa, sb in states:
            r = check(sa, sb)
            if r is None:  # Cycle detected
                used.add((a, b))
                return None
            if r == False:  # Opponent loses
                used.add((a, b))
                return True

        used.add((a, b))
        return False

    result = check(a, b)
    if result == True:
        return "Masha"  # Stas wins, Masha loses
    elif result == False:
        return "Stas"  # Stas loses, Masha wins
    elif result == None:
        return "Missing"  # Draw/Game can't end
    else:
        return "Stas"

