    # Find connected components and their sizes
    sizes = []
    visited = [False] * (n + 1)

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            stack = [i]
            visited[i] = True
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            sizes.append(size)

    # Generate lucky numbers up to n
    def generate_lucky_numbers(max_n):
        lucky = []
        for length in range(1, 6):  # 1 to 5 digit numbers (100000 has 6 digits)
            for i in range(1 << length):
                num = 0
                for digit_idx in range(length):
                    bit = (i >> digit_idx) & 1
                    num = num * 10 + (4 if bit == 0 else 7)
                if num <= max_n:
                    lucky.append(num)
        return sorted(lucky)

    lucky_set = set(generate_lucky_numbers(n))

    # Check if any single component is already lucky
    for s in sizes:
        if s in lucky_set:
            return "0\n"

    # DP: dp[s] = minimum components needed to sum to s
    dp = {0: 0}

    for s in sizes:
        new_dp = dp.copy()
        for current_sum, components in dp.items():
            new_sum = current_sum + s
            new_components = components + 1
            if new_sum not in new_dp or new_dp[new_sum] > new_components:
                new_dp[new_sum] = new_components
