    for i in range(1, len(lines)):
        if i <= q:
            try:
                k_values.append(int(lines[i]))
            except:
                pass

    def count_digits_to(x):
        if x <= 0:
            return 0
        total = 0
        length = 1
        start = 1
        while start <= x:
            end = min(x, start * 10 - 1)
            count = end - start + 1
            total += length * count
            length += 1
            start *= 10
        return total

    def find_block(k):
        low, high = 1, 200000
        while low < high:
            mid = (low + high) // 2
            total = sum(count_digits_to(i) for i in range(1, mid + 1))
            if total >= k:
                high = mid
            else:
                low = mid + 1
        return low

    def find_num_in_block(pos_in_block, block):
        low, high = 1, block
        while low < high:
            mid = (low + high) // 2
            length = count_digits_to(mid)
            if length <= pos_in_block:
                low = mid + 1
            else:
                high = mid
        num = low
        prev = count_digits_to(num - 1) if num > 1 else 0
        pos_in = pos_in_block - prev
        return int(str(num)[pos_in])

    results = []
    for k in k_values:
        block = find_block(k)
        prev_cum = sum(count_digits_to(i) for i in range(1, block))
        pos_in_block = k - prev_cum - 1
        results.append(str(find_num_in_block(pos_in_block, block)))

    return '\n'.join(results) if results else ''


