    for line in lines[1:q+1]:
        if not line.strip():
            continue
        l, r = map(int, line.split())

        if l == r:
            output.append(str(inversions))
            continue

        u = arr[l]
        v = arr[r]

        if u == v:
            output.append(str(inversions))
            arr[l], arr[r] = arr[r], arr[l]
            continue

        # Calculate number of inversions after swap
        # Formula:
        # Change in lr pair: +1 if u > v else -1 (when l < r)
        # Change due to middle elements: -2 * count(arr[k] between min and max for l < k < r)

        change = 0
        if l < r:
            change = -1 if u > v else 1
        else:
            change = 1 if u > v else -1

        cnt_between = 0
        if l < r:
            min_val, max_val = min(u, v), max(u, v)
            for k in range(l + 1, r):
                if arr[k] > min_val and arr[k] < max_val:
                    cnt_between += 1
            change -= 2 * cnt_between
        else:
            min_val, max_val = min(u, v), max(u, v)
            for k in range(r + 1, l):
                if arr[k] > min_val and arr[k] < max_val:
                    cnt_between += 1
            change -= 2 * cnt_between

        inversions += change
        arr[l], arr[r] = arr[r], arr[l]
        output.append(str(inversions))

