import sys

def solution(input_str):
    # Parse the input
    lines = input_str.strip().split('\n')
    t = int(lines[0])

    # Precompute Fibonacci numbers up to 10^18
    fib = [1, 2]
    while fib[-1] <= 10**18:
        fib.append(fib[-1] + fib[-2])
    # Remove the last one if it exceeds 10^18
    if fib[-1] > 10**18:
        fib.pop()

    RESULTS = []

    for i in range(1, t + 1):
        n = int(lines[i])
        RESULTS.append(str(compute_decompositions(n, fib)))

    return '\n'.join(RESULTS)

def get_index_bound(n, fib):
    """Find the largest index such that fib[index] <= n"""
    idx = 0
    for i in range(len(fib) - 1, -1, -1):
        if fib[i] <= n:
            idx = i
            break
    return idx

def compute_decompositions(n, fib):
    memo = {}

    def count_ways(target, start_idx):
        if target == 0:
            return 0  # We'll use mask to track valid ways
        if target == 1:
            return 1  # Only {1}
        if target > 10**16 or target < 0:
            return 0

        key = (target, start_idx)
        if key in memo:
            return memo[key]

        result = compute_mathematical_count(target, start_idx, fib)
        memo[key] = result
        return result

    return compute_mathematical_count(n, 0, fib)

def compute_mathematical_count(target, start_idx, fib):
    """
    Count the number of ways to decompose target using Fibonacci numbers
    from index start_idx onwards where each Fibonacci number can be used at most once
    """
    if target == 0:
        return 0
    if start_idx >= len(fib):
        return 1 if target == 0 else 0
    if fib[start_idx] > target:
        return compute_mathematical_count(target, start_idx + 1, fib)

    # Try including and excluding each Fibonacci number
    result = 0
    result += compute_mathematical_count(target, start_idx + 1, fib)  # Exclude

    if fib[start_idx] <= target:
        # Include this Fibonacci number
        remaining = target - fib[start_idx]
        # Now use Fibonacci numbers larger than the current one to avoid duplication
        # But we can also use the previous ones since we can't use consecutive
        # 
        # Actually, we need to be smarter here - let's use a simpler approach
        # We'll try to use the next available Fibonacci after this one, but we can also 
        # go back and use smaller ones
        result += compute_mathematical_count(remaining, start_idx + 1, fib)

    return result
